76	     * a space, and the national digits grouped in threes separated by spaces, e.g.
77	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}. The raw {@code telephone} is
78	     * left unchanged in E.164 form.
79	     */
80	    default String telephoneDisplay(Owner owner) {
81	        if (owner == null) {
82	            return null;
83	        }
84	        return TelephoneNormalizer.toDisplay(owner.getTelephone());
85	    }
