87	    /**
88	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}: the customer
89	     * code, the literal {@code '-M'}, and the last two digits of the registrationDate year.
90	     * Returns {@code null} unless both the customer code and registration date are present.
91	     */
92	    default String membershipNumber(Owner owner) {
93	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
94	            return null;
95	        }
96	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
97	        return owner.getCustomerCode() + "-M" + yy;
98	    }
