102	     * contained in the {@code customerCode}. Returns {@code null} when no customer code is present.
103	     */
104	    default Integer checkDigit(Owner owner) {
105	        if (owner == null || owner.getCustomerCode() == null) {
106	            return null;
107	        }
108	        String code = owner.getCustomerCode();
109	        int sum = 0;
110	        boolean dbl = true;
111	        for (int i = code.length() - 1; i >= 0; i--) {
112	            char c = code.charAt(i);
113	            if (c < '0' || c > '9') {
114	                continue;
115	            }
116	            int d = c - '0';
117	            if (dbl) {
118	                d *= 2;
119	                if (d > 9) {
120	                    d -= 9;
121	                }
122	            }
123	            sum += d;
124	            dbl = !dbl;
125	        }
126	        return (10 - (sum % 10)) % 10;
