142	        if (email != null && !email.isEmpty()) {
143	            level++;
144	        }
145	        Integer namesakeCount = owner.getNamesakeCount();
146	        if (namesakeCount != null && namesakeCount == 0) {
147	            level++;
148	        }
149	        LocalDate registrationDate = owner.getRegistrationDate();
150	        if (registrationDate != null
151	                && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365) {
152	            level++;
153	        }
154	        return Math.min(level, 4);
155	    }
