157	    /**
158	     * Derives the owner's locality (region) from the {@code customerCode}, whose form is
159	     * {@code '<REGION>-<HASH8>'}: the locality is the {@code REGION} segment before the first
160	     * hyphen. Returns {@code "UNKNOWN"} when the owner has no customer code yet.
161	     */
162	    default String locality(Owner owner) {
163	        if (owner == null) {
164	            return null;
165	        }
166	        String code = owner.getCustomerCode();
167	        if (code == null) {
168	            return "UNKNOWN";
169	        }
170	        int dash = code.indexOf('-');
171	        return dash >= 0 ? code.substring(0, dash) : code;
172	    }
173	
174	    /**
175	     * Whether the owner carries the bulk-signup warning (more than 80 owners already created
176	     * on its registration day at creation time). A {@code null} stored value is treated as
177	     * {@code false}, so the field is always present in the response.
178	     */
179	    default Boolean bulkSignupWarning(Owner owner) {
180	        if (owner == null) {
181	            return null;
182	        }
183	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
184	    }
185	
186	    /**
187	     * Whether the owner was flagged as a possible (soft) duplicate at creation time — not a hard
188	     * duplicate, but sharing an existing owner's last name and postcode with a different telephone.
189	     * A {@code null} stored value is treated as {@code false}, so the field is always present in the
190	     * response.
191	     */
192	    default Boolean possibleDuplicate(Owner owner) {
193	        if (owner == null) {
194	            return null;
195	        }
196	        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
197	    }
198	
199	    /**
200	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
201	     * present, otherwise {@code PHONE}.
202	     */
203	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
204	        if (owner == null) {
205	            return null;
206	        }
207	        String email = owner.getEmail();
208	        return (email != null && !email.isEmpty())
209	            ? OwnerDto.ContactPreferenceEnum.EMAIL
210	            : OwnerDto.ContactPreferenceEnum.PHONE;
211	    }
212	
213	    /**
214	     * Derives the owner's {@code identityKey}, the single value into which duplicate detection is
215	     * consolidated: {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
216	     */
217	    default String identityKey(Owner owner) {
218	        return IdentityKeyNormalizer.derive(owner);
219	    }
220	
