223	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} when 18 to 64, and
224	     * {@code SENIOR} when 65 or older. Returns {@code null} when no birth date is known (or when
225	     * no reference registration date is available), so the field is absent from the response.
226	     */
227	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
228	        if (owner == null || owner.getBirthDate() == null) {
229	            return null;
230	        }
231	        LocalDate reference = owner.getRegistrationDate();
232	        if (reference == null) {
233	            reference = LocalDate.now();
234	        }
235	        int age = Period.between(owner.getBirthDate(), reference).getYears();
236	        if (age < 18) {
237	            return OwnerDto.AgeBandEnum.MINOR;
238	        }
239	        if (age < 65) {
240	            return OwnerDto.AgeBandEnum.ADULT;
241	        }
242	        return OwnerDto.AgeBandEnum.SENIOR;
243	    }
